"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["53479"],{85442(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.grupo_formulario.candidato_como_membro_incompleto","status":422,"titulo":"O grupo que inclui o candidato n\xe3o identifica a ocorr\xeancia dele"},"descricao":{"codigo":"uniplus.grupo_formulario.candidato_como_membro_incompleto","requisitos":["UNI-REQ-0146"],"oQueAconteceu":["Um grupo repet\xedvel com `incluiCandidato` verdadeiro, como a composi\xe7\xe3o familiar, tem o pr\xf3prio candidato como um dos membros (UNI-REQ-0146). A ocorr\xeancia dele \xe9 a que responde `PROPRIO_CANDIDATO` no campo de parentesco, e sem esse campo nenhuma resposta identificaria a ocorr\xeancia do candidato. O grupo enviado n\xe3o cumpre uma destas condi\xe7\xf5es, e a mensagem diz qual:","- o `minimo` de ocorr\xeancias \xe9 menor que 1 (`field` igual a `grupos[i].minimo`): o grupo tem ao menos uma ocorr\xeancia, a do pr\xf3prio candidato;\\n- nenhum campo \xe9 o fato `PARENTESCO` (`field` igual a `grupos[i].subitens`): o grupo pede o parentesco em cada ocorr\xeancia;\\n- o campo `PARENTESCO` tem exibi\xe7\xe3o condicional ou obrigatoriedade diferente de `SEMPRE` (`field` igual a `grupos[i].subitens[j]`): o parentesco \xe9 sempre exibido e obrigat\xf3rio;\\n- o campo `PARENTESCO` tem uma restri\xe7\xe3o de op\xe7\xf5es formadas pelas respostas anteriores, ou de op\xe7\xf5es permitidas sem uma entrada incondicional que contenha `PROPRIO_CANDIDATO` (`field` igual a `grupos[i].subitens[j].restricoes`): as op\xe7\xf5es de parentesco admitem sempre o pr\xf3prio candidato.","Na cria\xe7\xe3o e na atualiza\xe7\xe3o de um modelo de formul\xe1rio o `field` come\xe7a por `conteudo.`. As recusas saem junto das demais recusas do grupo, e o campo cuja forma j\xe1 foi recusada conta como conforme aqui, para que s\xf3 a falta do parentesco seja apontada. Nada \xe9 gravado. Nos modelos, a confer\xeancia s\xf3 ocorre quando o conte\xfado foi lido sem recusa de leitura (como a de [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada)), e na atualiza\xe7\xe3o um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["Ajuste o grupo conforme a mensagem: declare `minimo` de ao menos 1, inclua o campo `PARENTESCO` com obrigatoriedade `SEMPRE` e sem exibi\xe7\xe3o condicional, e, se ele restringe as op\xe7\xf5es, inclua `PROPRIO_CANDIDATO` numa entrada de op\xe7\xf5es permitidas sem condi\xe7\xe3o. Se o grupo n\xe3o deve ter o candidato como membro, envie `incluiCandidato` falso."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o dos itens do formul\xe1rio"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Grupo formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3bbcc2307827ee8c6dab135295710bb856847f61"}}')}}]);